<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
/** HTML-only renderer. It never mutates quote data, resolves remote assets, or produces PDFs. */
class Estandar_Quotes_Document_Engine {
	public static function render_preview( array $view_model, array $definition ): string { return self::render( $view_model, $definition, 'preview' ); }
	public static function render_print( array $view_model, array $definition ): string { return self::render( $view_model, $definition, 'print' ); }
	private static function render( array $vm, array $definition, string $mode ): string {
		if ( ( $vm['contract'] ?? '' ) !== 'estandar_quote_view_model@1' || ( $definition['profile_key'] ?? '' ) !== ( $vm['profile_key'] ?? '' ) ) { throw new InvalidArgumentException( 'Incompatible document contract.' ); } Estandar_Quotes_Document_Definitions::validate( $definition, $vm['profile_key'] );
		$out = '<article class="esq-document esq-document--' . esc_attr( $mode ) . '"><style>.esq-document{max-width:900px;margin:0 auto;padding:32px;background:#fff;color:#202124;font:16px/1.45 Arial,sans-serif}.esq-document h1{margin:0}.esq-document section{margin:28px 0}.esq-document h2{border-bottom:1px solid #aaa;padding-bottom:7px;font-size:17px}.esq-document dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 24px}.esq-document dt{font-weight:bold}.esq-document dd{margin:0}.esq-document table{width:100%;border-collapse:collapse}.esq-document th,.esq-document td{padding:8px;border-bottom:1px solid #ddd;text-align:left}.esq-document .esq-muted{color:#666}@media print{.esq-document{max-width:none;padding:0}.esq-document section{break-inside:avoid}}</style>';
		$out .= '<header><h1>Cotización' . ( $vm['quote_number'] !== '' ? ' N° ' . esc_html( $vm['quote_number'] ) : '' ) . '</h1><p class="esq-muted">Emitida: ' . esc_html( $vm['issued_at'] ) . ' · Vigencia: ' . esc_html( $vm['expires_at'] ) . ' · UF: ' . esc_html( $vm['uf_rate'] ) . '</p></header>';
		foreach ( (array) $definition['blocks'] as $block ) { if ( $block['enabled'] ) { $out .= self::block( $block['id'], $vm ); } } return $out . '</article>';
	}
	private static function block( string $block, array $vm ): string {
		if ( $block === 'client' ) { return self::section( 'Datos del cliente', self::facts( array( 'Nombre' => $vm['client']['name'], 'RUT' => $vm['client']['tax_id'], 'Teléfono' => $vm['client']['phone'], 'Email' => $vm['client']['email'] ) ) ); }
		if ( $block === 'property' ) { $p = $vm['property']; return self::section( 'Proyecto y propiedad', self::facts( array( 'Proyecto' => $vm['project']['name'], 'Etapa' => $vm['project']['stage'], 'Unidad' => $p['unit_code'], 'Modelo' => $p['model'], 'Orientación' => $p['orientation'], 'Superficie total' => $p['area_total_m2'] ? $p['area_total_m2'] . ' m²' : '', 'Superficie útil' => ! empty( $vm['visibility']['usable_area'] ) ? $p['area_usable_m2'] . ' m²' : '', 'Pisos' => $p['floors'], 'Programa' => $p['bedrooms'] . ' D / ' . $p['bathrooms'] . ' B', 'Bodega' => ! empty( $vm['visibility']['storage'] ) ? 'Sí' : '', 'Estacionamiento' => ! empty( $vm['visibility']['parking'] ) ? 'Sí' : '' ) ) ); }
		if ( $block === 'investment' ) { return self::section( 'Valor de la inversión', '<table><thead><tr><th>Concepto</th><th>Total UF</th><th>Total CLP</th></tr></thead><tbody><tr><td>Valor total</td><td>' . esc_html( $vm['investment']['total_uf'] ) . '</td><td>' . esc_html( $vm['investment']['total_clp'] ) . '</td></tr></tbody></table>' ); }
		if ( $block === 'conditions' && ! empty( $vm['visibility']['conditions'] ) ) { $items = ''; foreach ( (array) $vm['conditions']['items'] as $item ) { $text = is_array( $item ) ? ( $item['text'] ?? '' ) : (string) $item; if ( $text !== '' ) { $items .= '<li>' . esc_html( $text ) . '</li>'; } } return self::section( 'Condiciones', '<ul>' . $items . '</ul>' ); }
		if ( $block === 'sales_room' ) { return self::section( 'Datos sala de venta', self::facts( $vm['project']['sales_room'] ) ); }
		if ( $block === 'financing' && ! empty( $vm['visibility']['financing'] ) ) { $rows = ''; foreach ( $vm['financing'] as $row ) { $rows .= '<tr><td>' . esc_html( (string) $row['years'] ) . '</td><td>' . esc_html( $row['payment_uf'] ) . '</td><td>' . esc_html( $row['payment_clp'] ) . '</td><td>' . esc_html( $row['minimum_income'] ) . '</td></tr>'; } return self::section( 'Financiamiento', '<table><thead><tr><th>Años</th><th>Valor mes UF</th><th>Valor mes CLP</th><th>Renta mínima</th></tr></thead><tbody>' . $rows . '</tbody></table>' ); }
		if ( $block === 'images' && ! empty( $vm['visibility']['images'] ) ) { return self::section( 'Imágenes y plantas', '<p class="esq-muted">Activos referenciados en el snapshot: ' . esc_html( (string) count( $vm['property']['images'] ) ) . '. La resolución de archivos corresponde a un adaptador posterior.</p>' ); }
		return '';
	}
	private static function facts( array $facts ): string { $html = '<dl>'; foreach ( $facts as $label => $value ) { if ( $value === '' || $value === null || $value === false ) { continue; } $html .= '<div><dt>' . esc_html( ucwords( str_replace( '_', ' ', (string) $label ) ) ) . '</dt><dd>' . esc_html( (string) $value ) . '</dd></div>'; } return $html . '</dl>'; }
	private static function section( string $title, string $body ): string { return '<section><h2>' . esc_html( $title ) . '</h2>' . $body . '</section>'; }
}
